/* MedicCare.module.css */

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  padding-top: 94px;
  position: relative;
  overflow-x: hidden;
}

.root,
.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

/* ------------------------------------
   TYPOGRAPHY
------------------------------------- */
.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  line-height: inherit;
  font-weight: 700;
}

.root h1 {
  font-size: 48px;
  line-height: normal;
}

.root h2 {
  font-size: 36px;
}

.root h3 {
  font-size: 32px;
}

.root h4 {
  font-size: 28px;
}

.root h5 {
  font-size: 24px;
}

.root h6 {
  font-size: 22px;
}

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: all 0.3s;
  touch-action: manipulation;
}

.root a:hover {
  color: var(--vt-accent-ink);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* ------------------------------------
   NAVIGATION
------------------------------------- */
.nav {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.05);
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
  padding-top: 20px;
  padding-bottom: 20px;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.navLinksLeft,
.navLinksRight {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.navLinksLeft a,
.navLinksRight a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
  transition: color 0.3s;
}

.navLinksLeft a:hover,
.navLinksRight a:hover {
  color: var(--vt-ink);
}

.logo {
  text-align: center;
  margin: 0 30px;
}

.brand {
  color: var(--vt-accent-ink);
  font-size: 24px;
  font-weight: 700;
  line-height: 1.2;
}

.brand strong {
  color: var(--vt-ink-soft);
  font-size: 12px;
  position: relative;
  bottom: 5px;
  display: block;
  font-weight: 600;
}

/* ------------------------------------
   HERO
------------------------------------- */
.hero {
  padding-top: 0;
}

.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scroll-behavior: smooth;
  height: 580px;
  position: relative;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  position: relative;
  overflow: hidden;
}

.heroImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  pointer-events: auto;
}

.heroText h1 {
  margin-top: auto;
  margin-bottom: 0.5rem;
  color: var(--vt-ink);
}

.heroWord {
  color: var(--vt-accent-ink);
  display: inline-block;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.5rem;
  margin-top: 1rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent-ink);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  overflow: hidden;
  position: relative;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
  transition: color 0.3s, background-color 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent-ink);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  text-align: center;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0;
}

/* ------------------------------------
   SECTION PADDING & CONTAINER
------------------------------------- */
.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.row {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

/* ------------------------------------
   ABOUT
------------------------------------- */
.about {
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.colFull {
  flex: 1 1 100%;
}

/* ------------------------------------
   GALLERY
------------------------------------- */
.gallery {
  padding: 0;
}

.gallery .row {
  gap: 0;
}

.galleryCol {
  flex: 1 1 50%;
  padding: 0;
}

.galleryImg {
  width: 100%;
  height: auto;
  display: block;
}

/* ------------------------------------
   TIMELINE
------------------------------------- */
.timelineSection {
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.timelineHeading {
  text-align: center;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNode {
  position: relative;
  display: flex;
  align-items: flex-start;
  margin-bottom: 2rem;
}

.timelineOdd {
  flex-direction: row;
}

.timelineEven {
  flex-direction: row-reverse;
}

.timelineContent {
  position: relative;
  border-radius: 0.25rem;
  padding: 0;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  flex: 1;
  z-index: 2;
}

.timelineOdd .timelineContent {
  margin-right: 2rem;
}

.timelineEven .timelineContent {
  margin-left: 2rem;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
}

.timelineOdd .timelineContent h3::after,
.timelineOdd .timelineContent p {
  text-align: right;
}

.timelineEven .timelineContent h3::after,
.timelineEven .timelineContent p {
  text-align: left;
}

.timelineOdd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineEven .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIcon {
  position: relative;
  z-index: 100;
  flex: 0 0 80px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.timelineIcon::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, 0);
  z-index: 1;
}

.timelineIcon span {
  position: relative;
  z-index: 100;
  font-size: 32px;
  color: var(--vt-accent-ink);
  line-height: 80px;
  text-align: center;
  display: block;
}

.timelineDate {
  flex: 1;
  text-align: left;
  padding: 1rem 2rem;
}

.timelineOdd .timelineDate {
  text-align: left;
}

.timelineEven .timelineDate {
  text-align: right;
}

/* ------------------------------------
   FOOTER
------------------------------------- */
.footer {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footer .row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.footerCol {
  min-width: 0;
}

.footerCol h5 {
  margin-bottom: 1rem;
  color: var(--vt-ink);
}

.footerCol p,
.footerCol a {
  color: var(--vt-ink-soft);
  margin-bottom: 0.5rem;
  display: block;
}

.footerCol a:hover {
  color: var(--vt-accent-ink);
}

.copyright {
  text-align: center;
  margin-top: 3rem;
  font-size: 16px;
  color: var(--vt-ink-soft);
}

/* ------------------------------------
   RESPONSIVE
------------------------------------- */
@media screen and (min-width: 1600px) {
  .heroSlides {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .root h1 {
    font-size: 38px;
  }

  .root h2 {
    font-size: 32px;
  }

  .root h3 {
    font-size: 26px;
  }

  .root h4 {
    font-size: 24px;
  }

  .root h5 {
    font-size: 20px;
  }

  .root h6 {
    font-size: 18px;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .navLinksLeft a,
  .navLinksRight a {
    padding-top: 5px;
    padding-bottom: 10px;
  }

  .heroSlides {
    height: inherit;
  }

  .heroText {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .timeline::before {
    left: 50%;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .timeline::before {
    top: 60px;
    left: 33px;
    height: 90%;
    transform: translateX(-50%);
  }

  .timelineNode {
    flex-direction: column;
    align-items: flex-start;
    margin-left: 50px;
  }

  .timelineOdd .timelineContent,
  .timelineEven .timelineContent {
    margin: 0;
  }

  .timelineOdd .timelineContent h3::after,
  .timelineEven .timelineContent h3::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
  }

  .timelineOdd .timelineContent h3,
  .timelineOdd .timelineContent p,
  .timelineEven .timelineContent h3,
  .timelineEven .timelineContent p {
    text-align: left;
  }

  .timelineIcon {
    position: absolute;
    left: 0;
    top: 60px;
    flex: 0 0 auto;
  }

  .timelineIcon::before {
    width: 75px;
    height: 75px;
  }

  .timelineIcon span {
    line-height: 75px;
  }

  .timelineDate {
    text-align: left;
    padding-left: 0;
  }

  .footer .row {
    grid-template-columns: 1fr;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
    height: 87%;
  }

  .timelineIcon {
    left: -10px;
  }

  .timelineIcon::before {
    width: 70px;
    height: 70px;
  }

  .timelineIcon span {
    line-height: 70px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }
}
